import{_ as a}from"./chunks/712f31a2f5a4af8ae0420094af456f19.CH8-nVHU.js";import{_ as e,c as d,a2 as r,o as s}from"./chunks/framework.Bzjhwp8w.js";const u=JSON.parse('{"title":"Langflow 中的内存组件","description":"Langflow 中的内存组件","frontmatter":{"title":"Langflow 中的内存组件","description":"Langflow 中的内存组件","layout":"doc"},"headers":[],"relativePath":"langflow/components-memories.md","filePath":"langflow/components-memories.md"}'),o={name:"langflow/components-memories.md"};function h(i,t,n,l,m,p){return s(),d("div",null,t[0]||(t[0]=[r('<h1 id="langflow-中的内存组件" tabindex="-1">Langflow 中的内存组件 <a class="header-anchor" href="#langflow-中的内存组件" aria-label="Permalink to &quot;Langflow 中的内存组件&quot;">​</a></h1><p>内存组件通过 <code>session_id</code> 存储和检索聊天消息。</p><p>它们与向量存储组件不同，因为它们专为从外部数据库存储和检索聊天消息而构建。</p><p>内存组件提供对其各自外部数据库<strong>作为内存</strong>的访问。这使得大型语言模型（LLMs）或<a href="./URL.html">代理</a>能够访问外部内存以实现持久性和上下文保留。</p><h2 id="使用内存组件于流程中" tabindex="-1">使用内存组件于流程中 <a class="header-anchor" href="#使用内存组件于流程中" aria-label="Permalink to &quot;使用内存组件于流程中&quot;">​</a></h2><p>此示例流程使用 <strong>Astra DB 聊天记忆</strong> 组件及 <strong>存储消息</strong> 和 <strong>聊天记忆</strong> 组件来存储和检索聊天历史。</p><p><strong>存储消息</strong> 辅助组件将聊天记忆存储为 <a href="./URL.html">数据</a> 对象，而 <strong>消息历史</strong> 辅助组件则以 <a href="./URL.html">数据</a> 对象或字符串的形式检索聊天消息。</p><p><img src="'+a+'" alt="Sample Flow storing Chat Memory in AstraDB"></p><h2 id="astradbchatmemory-组件" tabindex="-1">AstraDBChatMemory 组件 <a class="header-anchor" href="#astradbchatmemory-组件" aria-label="Permalink to &quot;AstraDBChatMemory 组件&quot;">​</a></h2><p>该组件创建一个 <code>AstraDBChatMessageHistory</code> 实例，用于通过 Astra DB 存储和检索聊天消息。Astra DB 是一种云原生数据库服务。</p><h3 id="inputs" tabindex="-1">Inputs <a class="header-anchor" href="#inputs" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>collection_name</td><td>String</td><td>用于存储消息的 Astra DB 集合名称。必填。</td></tr><tr><td>token</td><td>SecretString</td><td>用于访问 Astra DB 的认证令牌。必填。</td></tr><tr><td>api_endpoint</td><td>SecretString</td><td>Astra DB 服务的 API 端点 URL。必填。</td></tr><tr><td>namespace</td><td>String</td><td>Astra DB 中集合的可选命名空间。</td></tr><tr><td>session_id</td><td>MessageText</td><td>聊天会话 ID。如果未提供，则使用当前会话 ID。</td></tr></tbody></table><h3 id="outputs" tabindex="-1">Outputs <a class="header-anchor" href="#outputs" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>message_history</td><td>BaseChatMessageHistory</td><td>会话中 AstraDBChatMessageHistory 的一个实例。</td></tr></tbody></table><h2 id="cassandrachatmemory-组件" tabindex="-1">CassandraChatMemory 组件 <a class="header-anchor" href="#cassandrachatmemory-组件" aria-label="Permalink to &quot;CassandraChatMemory 组件&quot;">​</a></h2><p>该组件创建一个 <code>CassandraChatMessageHistory</code> 实例，支持使用 Apache Cassandra 或 DataStax Astra DB 存储和检索聊天消息。</p><h3 id="输入" tabindex="-1">输入 <a class="header-anchor" href="#输入" aria-label="Permalink to &quot;输入&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>database_ref</td><td>MessageText</td><td>Cassandra 的连接点或 Astra DB 数据库 ID。必填项。</td></tr><tr><td>username</td><td>MessageText</td><td>Cassandra 的用户名（Astra DB 可留空）。</td></tr><tr><td>token</td><td>SecretString</td><td>Cassandra 的密码或 Astra DB 的令牌。必填项。</td></tr><tr><td>keyspace</td><td>MessageText</td><td>Cassandra 的键空间或 Astra DB 的命名空间。必填项。</td></tr><tr><td>table_name</td><td>MessageText</td><td>用于存储消息的表或集合名称。必填项。</td></tr><tr><td>session_id</td><td>MessageText</td><td>聊天会话的唯一标识符。可选项。</td></tr><tr><td>cluster_kwargs</td><td>Dictionary</td><td>Cassandra 集群配置的其他关键字参数。可选项。</td></tr></tbody></table><h3 id="输出" tabindex="-1">输出 <a class="header-anchor" href="#输出" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>message_history</td><td>BaseChatMessageHistory</td><td>一个用于会话的 CassandraChatMessageHistory 实例。</td></tr></tbody></table><h2 id="mem0-chat-memory" tabindex="-1">Mem0 Chat Memory <a class="header-anchor" href="#mem0-chat-memory" aria-label="Permalink to &quot;Mem0 Chat Memory&quot;">​</a></h2><p>Mem0 Chat Memory 组件使用 Mem0 内存存储来检索和存储聊天消息。</p><h3 id="inputs-1" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-1" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>mem0_config</td><td>Mem0 配置</td><td>用于初始化 Mem0 内存实例的配置字典。</td></tr><tr><td>ingest_message</td><td>要导入的消息</td><td>要导入到 Mem0 内存中的消息内容。</td></tr><tr><td>existing_memory</td><td>现有内存实例</td><td>可选的现有 Mem0 内存实例。</td></tr><tr><td>user_id</td><td>用户 ID</td><td>与消息相关的用户标识符。</td></tr><tr><td>search_query</td><td>搜索查询</td><td>用于在 Mem0 中搜索相关记忆的输入文本。</td></tr><tr><td>mem0_api_key</td><td>Mem0 API 密钥</td><td>Mem0 平台的 API 密钥（若使用本地版本请留空）。</td></tr><tr><td>metadata</td><td>元数据</td><td>要与导入消息相关联的附加元数据。</td></tr><tr><td>openai_api_key</td><td>OpenAI API 密钥</td><td>OpenAI 的 API 密钥。如果使用 OpenAI 嵌入而没有提供相应配置，则需要此项。</td></tr></tbody></table><h3 id="输出-1" tabindex="-1">输出 <a class="header-anchor" href="#输出-1" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>memory</td><td>Mem0 Memory</td><td>处理数据后生成的 Mem0 Memory 对象。</td></tr><tr><td>search_results</td><td>搜索结果</td><td>查询 Mem0 memory 后的搜索结果。</td></tr></tbody></table><h2 id="redis-聊天内存" tabindex="-1">Redis 聊天内存 <a class="header-anchor" href="#redis-聊天内存" aria-label="Permalink to &quot;Redis 聊天内存&quot;">​</a></h2><p>该组件从 Redis 中获取并存储聊天消息。</p><h3 id="inputs-2" tabindex="-1">Inputs <a class="header-anchor" href="#inputs-2" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>host</td><td>hostname</td><td>IP地址或主机名。</td></tr><tr><td>port</td><td>port</td><td>Redis端口号。</td></tr><tr><td>database</td><td>database</td><td>Redis数据库。</td></tr><tr><td>username</td><td>Username</td><td>Redis用户名。</td></tr><tr><td>password</td><td>Password</td><td>用户名的密码。</td></tr><tr><td>key_prefix</td><td>Key prefix</td><td>键前缀。</td></tr><tr><td>session_id</td><td>Session ID</td><td>消息的会话ID。</td></tr></tbody></table><h3 id="outputs-1" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-1" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Display Name</th><th>Info</th></tr></thead><tbody><tr><td>memory</td><td>Memory</td><td>The Redis chat message history object</td></tr></tbody></table><hr><h3 id="输出-2" tabindex="-1">输出 <a class="header-anchor" href="#输出-2" aria-label="Permalink to &quot;输出&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>显示名称</th><th>信息</th></tr></thead><tbody><tr><td>memory</td><td>Memory</td><td>Redis 聊天消息历史对象</td></tr></tbody></table><h2 id="zepchatmemory-组件" tabindex="-1">ZepChatMemory 组件 <a class="header-anchor" href="#zepchatmemory-组件" aria-label="Permalink to &quot;ZepChatMemory 组件&quot;">​</a></h2><p>该组件创建一个 <code>ZepChatMessageHistory</code> 实例，使得可以使用 Zep（大型语言模型的内存服务器）来存储和检索聊天消息。</p><h3 id="输入-1" tabindex="-1">输入 <a class="header-anchor" href="#输入-1" aria-label="Permalink to &quot;输入&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>url</td><td>MessageText</td><td>Zep 实例的 URL。必填。</td></tr><tr><td>api_key</td><td>SecretString</td><td>用于与 Zep 实例进行身份验证的 API 密钥。</td></tr><tr><td>api_base_path</td><td>Dropdown</td><td>要使用的 API 版本。选项：&quot;api/v1&quot; 或 &quot;api/v2&quot;。</td></tr><tr><td>session_id</td><td>MessageText</td><td>聊天会话的唯一标识符。可选。</td></tr></tbody></table><h3 id="outputs-2" tabindex="-1">Outputs <a class="header-anchor" href="#outputs-2" aria-label="Permalink to &quot;Outputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>message_history</td><td><code>BaseChatMessageHistory</code></td><td>ZepChatMessageHistory类的一个实例用于当前会话。</td></tr></tbody></table>',41)]))}const y=e(o,[["render",h]]);export{u as __pageData,y as default};
